import { randomUUID } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { WikiResultSchema } from "../packages/contracts/src/index";
import { expect, it } from "vitest";
import { SqliteWorkspaceRepository } from "../packages/infrastructure/src/index";
import { createSyntheticQuote, seedPublished } from "../packages/infrastructure/src/wiki-test.fixture";

it.each(["source_expired_history", "source_updated_new_reference"] as const)("A public source eligibility: %s", async (kind) => {
  const dir = mkdtempSync(join(tmpdir(), "tq-p1-eligibility-"));
  const file = join(dir, "synthetic.sqlite");
  const repo = new SqliteWorkspaceRepository(file);
  try {
    const actor = { actorId: "synthetic-review", origin: "human_ui" as const };
    repo.commit({ schemaVersion: 1, requestId: randomUUID(), idempotencyKey: randomUUID(), method: "workspace.create", payload: { name: "synthetic P1 probe" } }, actor);
    const quote = createSyntheticQuote(repo);
    const start = Date.parse(quote.createdAt);
    const expiresAt = new Date(start + 7200000).toISOString();
    const beforeExpiry = new Date(start + 3600000).toISOString();
    const seed = await seedPublished(file, repo, quote.workspaceId, {
      locale: "en", kind: "rule", rules: [{ ruleId: randomUUID(), category: "commercial_terms", field: "payment", condition: { kind: "required" }, title: "synthetic", message: "synthetic", failureSeverity: "block", suggestedAction: "human review" }],
      ...(kind === "source_expired_history" ? { sourceValidity: { status: "confirmed" as const, validFrom: null, validUntil: expiresAt } } : {}),
    });
    const host = (now: string) => ({ ...actor, workspaceId: quote.workspaceId, now });
    const resolve = (purpose: "history" | "new_reference", now: string) => repo.executeWiki({ schemaVersion: 1, requestId: randomUUID(), method: "wiki.resolveCitation", payload: { citation: seed.citation, purpose, scope: { platform: quote.scenario.platform, market: quote.scenario.market, category: quote.scenario.category }, locale: "en" } }, host(now));
    const control = WikiResultSchema.parse(await resolve("new_reference", beforeExpiry));
    expect(control).toMatchObject({ ok: true, data: { kind: "citationResolution", resolution: { eligibility: { eligible: true } } } });
    let updatedSourcePin: { sourceRevisionId: string; version: number } | null = null;
    if (kind === "source_updated_new_reference") {
      const old = seed.sources[0]!;
      const staged = WikiResultSchema.parse(await repo.executeWiki({ schemaVersion: 1, requestId: randomUUID(), idempotencyKey: randomUUID(), method: "source.stage", payload: { sourceId: old.sourceId, expectedVersion: old.version, label: old.label, sourceStatus: old.sourceStatus, mediaType: old.mediaType, sourceText: "synthetic updated source", acquiredAt: old.acquiredAt, sourceUri: null, permissionNote: old.permissionNote, validity: old.validity } }, host(beforeExpiry)));
      expect(staged).toMatchObject({ ok: true, data: { kind: "sourceRevision", revision: { version: 2 } } });
      if (staged.ok && staged.data.kind === "sourceRevision") updatedSourcePin = { sourceRevisionId: staged.data.revision.sourceRevisionId, version: staged.data.revision.version };
    }
    const raw = await resolve(kind === "source_expired_history" ? "history" : "new_reference", expiresAt);
    const parsed = WikiResultSchema.safeParse(raw);
    console.log("P1_ELIGIBILITY_OBSERVATION " + JSON.stringify({ kind, controlValid: true, updatedSourcePin, publicSchemaValid: parsed.success, result: raw, schemaIssues: parsed.success ? [] : parsed.error.issues.map(i => i.message) }));
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;
    if (kind === "source_updated_new_reference") expect(parsed.data.ok).toBe(false);
    else expect(parsed.data).toMatchObject({ ok: true, data: { kind: "citationResolution", resolution: { eligibility: { eligible: false } } } });
  } finally {
    repo.close(); rmSync(dir, { recursive: true, force: true });
  }
});

